SELECT EMP2.EMPNO, EMP2.ENAME, EMP2.JOB, EMP2.MGR, EMP2.HIREDATE, EMP2.SAL, EMP2.COMM, EMP2.DEPTNO, EMP2.SLACKER FROM EMP AS EMP2 INNER JOIN (SELECT DEPTNO, TRUE AS F1 FROM EMP GROUP BY DEPTNO) AS t5 ON EMP2.DEPTNO = t5.DEPTNO LEFT JOIN (SELECT JOB, TRUE AS F1 FROM EMP WHERE SAL = 34 GROUP BY JOB) AS t9 ON EMP2.JOB = t9.JOB WHERE t9.F1 IS NULL
